using AspPlayground.Data;
using AspPlayground.DTOs;
using AspPlayground.Entities;
using AspPlayground.Services;
using AspPlayground.Tests.Helpers;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

namespace AspPlayground.Tests.UnitTests.Services;

// Tests the service with a real (in-memory SQLite) database, so the queries really run.
// xUnit creates a new instance of this class for every test, so every test gets its own empty database.
// some of the code you'll see here is generated by Claude Code :)
public class VehicleServiceTests : IDisposable
{
    private readonly SqliteConnection _connection;
    private readonly AppDbContext _context;
    private readonly VehicleService _service;

    public VehicleServiceTests()
    {
        // The in-memory database lives as long as this connection is open
        _connection = new SqliteConnection("DataSource=:memory:");
        _connection.Open();

        DbContextOptions<AppDbContext> options = new DbContextOptionsBuilder<AppDbContext>()
            .UseSqlite(_connection)
            .Options;

        _context = new AppDbContext(options);
        _context.Database.EnsureCreated();

        _service = new VehicleService(_context);
    }

    public void Dispose()
    {
        _context.Dispose();
        _connection.Dispose();
    }

    // Saves a vehicle directly in the database and returns its id
    private async Task<int> AddVehicleAsync(string brand = "Chery", string model = "Tiggo 8 Pro", int year = 2023)
    {
        Vehicle vehicle = TestData.CreateVehicle(brand, model, year);
        _context.Vehicles.Add(vehicle);
        await _context.SaveChangesAsync();
        return vehicle.Id;
    }

    // ---------- GetAllAsync ----------

    [Fact]
    public async Task GetAllAsync_NoVehicles_ReturnsEmptyPage()
    {
        PagedResponse<VehicleResponse> page = await _service.GetAllAsync(new PaginationQuery());

        Assert.Empty(page.Items);
        Assert.Equal(0, page.TotalCount);
    }

    [Fact]
    public async Task GetAllAsync_SeveralVehicles_ReturnsNewestYearFirst()
    {
        await AddVehicleAsync(year: 2020);
        await AddVehicleAsync(year: 2024);
        await AddVehicleAsync(year: 2022);

        PagedResponse<VehicleResponse> page = await _service.GetAllAsync(new PaginationQuery());

        Assert.Equal(3, page.Items.Count);
        Assert.Equal(2024, page.Items[0].ManufacturingYear);
        Assert.Equal(2022, page.Items[1].ManufacturingYear);
        Assert.Equal(2020, page.Items[2].ManufacturingYear);
    }

    [Fact]
    public async Task GetAllAsync_SecondPage_ReturnsTheRemainingVehicles()
    {
        for (int i = 0; i < 5; i++)
        {
            await AddVehicleAsync(year: 2000 + i);
        }

        PagedResponse<VehicleResponse> page = await _service.GetAllAsync(new PaginationQuery { Page = 2, PageSize = 3 });

        Assert.Equal(2, page.Items.Count);
        Assert.Equal(5, page.TotalCount);
        Assert.Equal(2, page.TotalPages);
    }

    // ---------- GetByIdAsync ----------

    [Fact]
    public async Task GetByIdAsync_VehicleExists_ReturnsIt()
    {
        int id = await AddVehicleAsync(brand: "OMODA", model: "OMODA 5");

        VehicleResponse? result = await _service.GetByIdAsync(id);

        Assert.NotNull(result);
        Assert.Equal("OMODA", result.Brand);
        Assert.Equal("OMODA 5", result.Model);
    }

    [Fact]
    public async Task GetByIdAsync_VehicleDoesNotExist_ReturnsNull()
    {
        VehicleResponse? result = await _service.GetByIdAsync(999);

        Assert.Null(result);
    }

    // ---------- CreateAsync ----------

    [Fact]
    public async Task CreateAsync_ValidRequest_ReturnsTheNewVehicleWithAnId()
    {
        VehicleResponse result = await _service.CreateAsync(TestData.CreateRequest());

        Assert.True(result.Id > 0);
        Assert.Equal("Chery", result.Brand);
        Assert.Equal(2023, result.ManufacturingYear);
    }

    [Fact]
    public async Task CreateAsync_ValidRequest_SavesItInTheDatabase()
    {
        await _service.CreateAsync(TestData.CreateRequest());

        Assert.Equal(1, await _context.Vehicles.CountAsync());
    }

    // ---------- UpdateAsync ----------

    [Fact]
    public async Task UpdateAsync_VehicleExists_ChangesTheValues()
    {
        int id = await AddVehicleAsync();
        VehicleRequest request = TestData.CreateRequest();
        request.Brand = "JAECOO";
        request.Mileage = 500;

        VehicleResponse? result = await _service.UpdateAsync(id, request);

        Assert.NotNull(result);
        Assert.Equal("JAECOO", result.Brand);
        Assert.Equal(500, result.Mileage);
    }

    [Fact]
    public async Task UpdateAsync_VehicleDoesNotExist_ReturnsNull()
    {
        VehicleResponse? result = await _service.UpdateAsync(999, TestData.CreateRequest());

        Assert.Null(result);
    }

    // ---------- DeleteAsync ----------

    [Fact]
    public async Task DeleteAsync_VehicleExists_ReturnsTrueAndRemovesIt()
    {
        int id = await AddVehicleAsync();

        bool deleted = await _service.DeleteAsync(id);

        Assert.True(deleted);
        Assert.Equal(0, await _context.Vehicles.CountAsync());
    }

    [Fact]
    public async Task DeleteAsync_VehicleDoesNotExist_ReturnsFalse()
    {
        bool deleted = await _service.DeleteAsync(999);

        Assert.False(deleted);
    }

    // ---------- FilterByBrandAndModelAsync ----------

    [Fact]
    public async Task FilterByBrandAndModelAsync_ByBrand_ReturnsOnlyThatBrand()
    {
        await AddVehicleAsync(brand: "Chery");
        await AddVehicleAsync(brand: "Chery");
        await AddVehicleAsync(brand: "OMODA");

        PagedResponse<VehicleResponse> page = await _service.FilterByBrandAndModelAsync("Chery", null, new PaginationQuery());

        Assert.Equal(2, page.Items.Count);
        Assert.All(page.Items, vehicle => Assert.Equal("Chery", vehicle.Brand));
    }

    [Fact]
    public async Task FilterByBrandAndModelAsync_ByBrandAndModel_ReturnsOnlyThatModel()
    {
        await AddVehicleAsync(brand: "Chery", model: "Tiggo 8 Pro");
        await AddVehicleAsync(brand: "Chery", model: "Tiggo 7 Pro");

        PagedResponse<VehicleResponse> page = await _service.FilterByBrandAndModelAsync("Chery", "Tiggo 7 Pro", new PaginationQuery());

        VehicleResponse vehicle = Assert.Single(page.Items);
        Assert.Equal("Tiggo 7 Pro", vehicle.Model);
    }

    [Fact]
    public async Task FilterByBrandAndModelAsync_NoFilter_ReturnsEverything()
    {
        await AddVehicleAsync(brand: "Chery");
        await AddVehicleAsync(brand: "OMODA");

        PagedResponse<VehicleResponse> page = await _service.FilterByBrandAndModelAsync(null, null, new PaginationQuery());

        Assert.Equal(2, page.Items.Count);
    }

    [Fact]
    public async Task FilterByBrandAndModelAsync_NothingMatches_ReturnsEmptyPage()
    {
        await AddVehicleAsync(brand: "Chery");

        PagedResponse<VehicleResponse> page = await _service.FilterByBrandAndModelAsync("Tesla", null, new PaginationQuery());

        Assert.Empty(page.Items);
        Assert.Equal(0, page.TotalCount);
    }

    [Fact]
    public async Task FilterByBrandAndModelAsync_TotalCountOnlyCountsTheMatches()
    {
        await AddVehicleAsync(brand: "Chery");
        await AddVehicleAsync(brand: "Chery");
        await AddVehicleAsync(brand: "OMODA");

        PagedResponse<VehicleResponse> page = await _service.FilterByBrandAndModelAsync("Chery", null, new PaginationQuery());

        Assert.Equal(2, page.TotalCount);
    }

    // ---------- UpdateAvailabilityStatusAsync ----------

    [Fact]
    public async Task UpdateAvailabilityStatusAsync_VehicleExists_ChangesTheStatus()
    {
        int id = await AddVehicleAsync();

        VehicleResponse? result = await _service.UpdateAvailabilityStatusAsync(id, AvailabilityStatus.Sold);

        Assert.NotNull(result);
        Assert.Equal(AvailabilityStatus.Sold, result.AvailabilityStatus);
    }

    [Fact]
    public async Task UpdateAvailabilityStatusAsync_VehicleDoesNotExist_ReturnsNull()
    {
        VehicleResponse? result = await _service.UpdateAvailabilityStatusAsync(999, AvailabilityStatus.Sold);

        Assert.Null(result);
    }
}
